"""Named-source review; lattice evidence is distinct from full source eligibility."""
import json
import ledger as L
from review_batch_0001 import evidence

NOTES=[['10.1021/acssensors.7b00628', '9972970-se7b00628_si_001.pdf', '9972970', 'SI pp4–5 molecular synthesis and FigS2; p12 bibliography; retained ACS abstract search rendering', 'SI describes165bp duplex scaffold assembled from ten30/45nt oligos, rather than a demonstrated long scaffold folded by staples. P1/P2/P12 protrusions arise from specified LINK-to-PROT replacements; extending with SCAF-F/G/H yields255bp for ATP-triggered aptamer displacement. Publisher abstract calls this origami-based molecular assembly, creating a broad-scope classification question that cannot be settled from that label alone. Retain uncertain pending main Methods and scope adjudication; do not infer narrow lattice eligibility. Source diagram and full sequence/table checks pending.', ['Inspect main article and FigS2 topology; adjudicate broad origami-based design scope versus short-oligo duplex assembly explicitly.', 'Reconcile all8supplement references; follow BSC2017 conference counterpart lead, not yet acquired.']], ['10.1021/acsnano.7b08044', '10301766-nn7b08044_si_001.pdf', '10301766', 'SI pp2–4 assembly/conjugation/model methods; p7 references; p8 FigS1 caption; pp13–27 caption survey; pp28–29 table purposes', 'NuPOD rings use8064nt M13-derived circular scaffold and3-prime extended staples carrying inner/outer FG-nup handles or separate biotin functionalization handles. FigS1 distinguishes routing diagrams for0–32inner handles versus48inner/48outer handles; core equivalence across these maps is unverified. Nsp1 and Nup100 protein identity, copy number and MBP-tag cleavage are distinct from origami core changes. TableS1 contains amino-acid sequences, not DNA staples; S2 measured protein copy numbers, not synthesis recipes. MD ring is a fixed coarse cylinder of spheres; its stated radii/heights must not substitute for authored DNA routing. Full DNA staple set/native map and lattice remain to locate. p8 dense diagram extraction is unwieldy; geometric content not audited.', ['Inspect high-resolution FigS1 and obtain full native maps/staple sequences; determine exact core differences between handle-density versions.', 'Map inner/outer/protein/tag conditions independently; deferred movies remain unreviewed; verify narrow lattice/source eligibility.']], ['10.1021/acsnano.7b08233', '10325496-nn7b08233_si_001.pdf', '10325496', 'SI p3 FigS3/TableS1; pp4–8 core-table heading/tail; p8 TableS3; p9 TablesS4/S5 and folding-program caption', 'Origami pillar schematic is provided as caDNAno FigS3; sequence TableS2 spans pp4–8, but full routing/core composition not checked. TableS3 lists six polyA20 particle-binding strands for AgNP/AuNP and a separate biotin strand for PCP-streptavidin binding. TableS4 gives four extended pillar staples for biotin-strand binding; S5 gives the surface-immobilization biotin strand. These attachment roles must remain separate. TableS1 distinguishes gold/silver monomer/dimer optical-antenna populations; no inference that each population is a different origami core. Scaffold clone, exact reused pillar parent and lattice remain to establish from main Methods and map.', ['Acquire main Methods and trace pillar parent/scaffold/lattice; inspect FigS3 at readable resolution.', 'Audit core rows and replacement/extension identities against six particle handles, PCP binding and four surface attachment sites; no full source certification yet.']]]

def main():
    pubs={p['registry_key']:p for p in L.read('publication_reviews')}
    for key,name,fid,locator,note,questions in NOTES:
        p=pubs[key];ev=evidence(L.ROOT/'assets/sources/acs-expansion-20261104'/name,'https://ndownloader.figshare.com/files/'+fid,locator)
        p.update(review_stage='design_sources_reviewed',relevance='design_bearing',publication_type=['journal_article'],design_contributions=['uncertain'],catalog_eligibility='unresolved',access='partial',evidence=[ev],rationale=note,unresolved_questions=questions,reviewer='Codex named supplement sections and sequence-table inspection',run_id='B0011',date=L.DATE)
        if key=='10.1021/acssensors.7b00628':
            p['relevance']='uncertain'
            p['evidence'].append(evidence(L.HERE/'batch_0011_short_scaffold_search.json','https://pubs.acs.org/doi/10.1021/acssensors.7b00628','Publisher abstract retrieved via search; full main Methods not obtained'))
        L.upsert('publication_reviews',p,'Record explicit lattice and variant evidence while retaining source-completeness checks')
    b=next(b for b in L.read('batches') if b['batch_id']=='B0011')
    action='Reviewed short-scaffold sensing, NuPOD rings and PCP antennas:16/25first passes saved; short-scaffold relevance uncertain.'
    if action not in b['completed_actions']:b['completed_actions'].append(action)
    b.update(after_counts=L.counts(),validation=[L.validate()],next_queue=['Review9rotating B0011records; all15selected ACS first passes saved','Follow source parents and unresolved complete-source checks','Continue FNANO2012, abstracts, forward citations and author histories'])
    L.upsert('batches',b,'Checkpoint16/25 first passes; keep batch active')
    L.atomic(L.HERE/'batch_0011_fifth_audit.json',json.dumps(dict(batch_id='B0011',first_pass_count=16,input_count=25,complete_source_certifications=0,counts=L.counts(),validation=L.validate()),indent=2)+'\n')
    print(L.validate())
if __name__=='__main__':main()
